int QueueAppend(LQueue *Q, DataType x)
{    LQNode *p;
     if((p = (LQNode *)malloc(sizeof(LQNode))) == NULL)
     {     printf(" 内存空间不足! ");
           return 0;   }
     p->data = x;      p->next = NULL;
     if(Q->rear != NULL) Q->rear->next = p;
     Q->rear = p;
     if(Q->front == NULL) Q->front = p;
     return 1;
}
